calculation:
COUNTROWS(
    FILTER(
        VALUES(Stores[Store ID]),
        [POS Sales] = 0 || ISBLANK([POS Sales])
    )
)

IF (
    //If only one item in context then show the value
    HASONEFILTER ( 'Stores'[Store ID] ),
    MAX ( Walmart_Facts_STR_POD_ACT_1000_Store_Rollup[Traited Items] ),
    // Get all the stores that have any traited items for the selected context. This measure does not do sums    
    CALCULATE (
        DISTINCTCOUNT ( Walmart_Facts_STR_POD_ACT_1000_Item_Rollup[Item ID] ),
        FILTER (
            Walmart_Facts_STR_POD_ACT_1000_Item_Rollup,
            Walmart_Facts_STR_POD_ACT_1000_Item_Rollup[Traited Stores] > 0
        )
    )
)

